CREATE SEQUENCE stocktake_numbers;
CREATE TABLE stocktakes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE DEFAULT('CNT-'||lpad(nextval('stocktake_numbers')::text,8,'0')),project_id uuid NOT NULL REFERENCES projects(id),warehouse_id uuid NOT NULL REFERENCES warehouses(id),scope jsonb NOT NULL,snapshot_revision bigint NOT NULL REFERENCES inventory_revisions(id),snapshot_at timestamptz NOT NULL,snapshot_version int NOT NULL DEFAULT 1,current_pass int NOT NULL DEFAULT 1 CHECK(current_pass BETWEEN 1 AND 10),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','SUBMITTED','APPROVED','REJECTED')),assigned_to uuid NOT NULL REFERENCES users(id),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),close_revision bigint REFERENCES inventory_revisions(id),reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,review_note text,approved_report jsonb,version int NOT NULL DEFAULT 1);
CREATE TABLE stocktake_snapshot(stocktake_id uuid NOT NULL REFERENCES stocktakes(id),bundle_id uuid NOT NULL REFERENCES bundles(id),state jsonb NOT NULL,PRIMARY KEY(stocktake_id,bundle_id));
CREATE TABLE stocktake_observations(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,stocktake_id uuid NOT NULL REFERENCES stocktakes(id),pass int NOT NULL,bundle_no text NOT NULL,actual_location_id uuid NOT NULL REFERENCES locations(id),actual_weight numeric(14,6) NOT NULL CHECK(actual_weight>=0),observed_revision bigint NOT NULL REFERENCES inventory_revisions(id),counted_by uuid NOT NULL REFERENCES users(id),counted_at timestamptz NOT NULL,remark text NOT NULL,source text NOT NULL CHECK(source IN('MANUAL','EXCEL')),source_row int);
CREATE TABLE stocktake_reconciliations(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,stocktake_id uuid NOT NULL REFERENCES stocktakes(id),pass int NOT NULL,bundle_no text NOT NULL,covered_revision bigint NOT NULL REFERENCES inventory_revisions(id),reason text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE stocktake_steps(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,stocktake_id uuid NOT NULL REFERENCES stocktakes(id),action text NOT NULL,pass int NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),note text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TRIGGER stocktake_state BEFORE UPDATE OR DELETE ON stocktakes FOR EACH ROW EXECUTE FUNCTION v23_state_owner();
DO $$ DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['stocktake_snapshot','stocktake_observations','stocktake_reconciliations','stocktake_steps'] LOOP EXECUTE format('CREATE TRIGGER history_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION v23_immutable()',tab);END LOOP;END $$;
CREATE TRIGGER temporal_document AFTER INSERT OR UPDATE ON stocktakes FOR EACH ROW EXECUTE FUNCTION v24_source_capture();
CREATE FUNCTION v24_count_scope(s jsonb,f jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT s IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_each_text(f) k WHERE nullif(k.value,'') IS NOT NULL AND s->>k.key IS DISTINCT FROM k.value) $$;
CREATE FUNCTION v24_count_require(actor uuid,permission text,p uuid,w uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN PERFORM v23_require(actor,permission,p,NULL,w);END $$;
CREATE FUNCTION stocktake_create(actor uuid,p uuid,w uuid,f jsonb,assignee uuid) RETURNS stocktakes LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d stocktakes;r bigint;BEGIN
 r:=v24_revision();PERFORM v24_count_require(actor,'stocktake:write',p,w);PERFORM v24_count_require(assignee,'stocktake:write',p,w);
 IF NOT EXISTS(SELECT 1 FROM warehouses WHERE id=w AND project_id=p AND active) OR EXISTS(SELECT 1 FROM jsonb_object_keys(f) k WHERE k NOT IN('project_id','warehouse_id','yard_id','location_id','batch_id')) THEN RAISE EXCEPTION 'Invalid count scope' USING ERRCODE='23514';END IF;
 f:=f||jsonb_build_object('project_id',p,'warehouse_id',w);
 IF f->>'yard_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM yards WHERE id=(f->>'yard_id')::uuid AND warehouse_id=w AND project_id=p) OR f->>'location_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM locations WHERE id=(f->>'location_id')::uuid AND warehouse_id=w AND project_id=p AND(f->>'yard_id' IS NULL OR yard_id=(f->>'yard_id')::uuid)) OR f->>'batch_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM batches WHERE id=(f->>'batch_id')::uuid AND project_id=p) THEN RAISE EXCEPTION 'Scope relations mismatch' USING ERRCODE='23514';END IF;
 INSERT INTO stocktakes(project_id,warehouse_id,scope,snapshot_revision,snapshot_at,assigned_to,created_by) VALUES(p,w,f,r,v24_posting_time(),assignee,actor) RETURNING * INTO d;
 INSERT INTO stocktake_snapshot SELECT d.id,bundle_id,state FROM(SELECT DISTINCT ON(bundle_id) bundle_id,state FROM inventory_history WHERE revision_id<=r ORDER BY bundle_id,revision_id DESC) x WHERE state->>'physical_status'='IN_STOCK' AND v24_count_scope(state,f);
 INSERT INTO stocktake_steps(stocktake_id,action,pass,actor_id,note) VALUES(d.id,'CREATE',1,actor,'独立基准快照，含有效锁定及未正式离场装车库存');INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data) VALUES(actor,'stocktake_created','stocktakes',d.id::text,to_jsonb(d));RETURN d;END $$;
CREATE FUNCTION stocktake_report(actor uuid,doc uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d stocktakes;r bigint;result jsonb;BEGIN
 SELECT * INTO d FROM stocktakes WHERE id=doc;IF NOT FOUND THEN RAISE EXCEPTION 'Stocktake missing' USING ERRCODE='23514';END IF;PERFORM v24_count_require(actor,'stocktake:read',d.project_id,d.warehouse_id);IF d.status='APPROVED' THEN RETURN d.approved_report;END IF;r:=coalesce(d.close_revision,v24_revision());
 WITH latest AS(SELECT DISTINCT ON(bundle_id) bundle_id,state,revision_id FROM inventory_history WHERE revision_id<=r ORDER BY bundle_id,revision_id DESC),ending AS(SELECT * FROM latest WHERE state->>'physical_status'='IN_STOCK' AND v24_count_scope(state,d.scope)),obs AS(SELECT DISTINCT ON(bundle_no) * FROM stocktake_observations WHERE stocktake_id=doc AND pass=d.current_pass ORDER BY bundle_no,id),keys AS(SELECT state->>'bundle_no' AS no FROM stocktake_snapshot WHERE stocktake_id=doc UNION SELECT state->>'bundle_no' FROM ending UNION SELECT bundle_no FROM obs),raw AS(
 SELECT k.no,coalesce((base.state->>'weight')::numeric,0) AS opening,coalesce((e.state->>'weight')::numeric,0) AS closing,o.actual_weight,o.actual_location_id,ol.code AS actual_location,o.id AS observation_id,ob.state AS at_observation,CASE WHEN ob.state->>'physical_status'='IN_STOCK' AND v24_count_scope(ob.state,d.scope) THEN(ob.state->>'weight')::numeric ELSE 0 END AS observed_book,(SELECT count(*) FROM stocktake_observations WHERE stocktake_id=doc AND pass=d.current_pass AND bundle_no=k.no) AS occurrences,EXISTS(SELECT 1 FROM stocktake_reconciliations a WHERE a.stocktake_id=doc AND a.pass=d.current_pass AND a.bundle_no=k.no AND a.covered_revision>=e.revision_id) AS reconciled
 FROM keys k LEFT JOIN stocktake_snapshot base ON base.stocktake_id=doc AND base.state->>'bundle_no'=k.no LEFT JOIN ending e ON e.state->>'bundle_no'=k.no LEFT JOIN obs o ON o.bundle_no=k.no LEFT JOIN locations ol ON ol.id=o.actual_location_id LEFT JOIN LATERAL(SELECT state FROM inventory_history WHERE state->>'bundle_no'=k.no AND revision_id<=o.observed_revision ORDER BY revision_id DESC LIMIT 1) ob ON true),rows AS(
 SELECT *,CASE WHEN observation_id IS NOT NULL THEN actual_weight+closing-observed_book WHEN opening=0 AND closing>0 AND reconciled THEN closing ELSE 0 END AS rolled_count,CASE WHEN occurrences>1 THEN 'DUPLICATE' WHEN observation_id IS NULL AND closing=0 THEN 'REMOVED_BY_FLOW' WHEN observation_id IS NULL AND opening=0 AND closing>0 THEN CASE WHEN reconciled THEN 'RECONCILED_MOVEMENT' ELSE 'UNVERIFIED_MOVEMENT' END WHEN observation_id IS NULL AND closing>0 THEN 'LOSS' WHEN observed_book=0 THEN 'GAIN' WHEN actual_location_id::text IS DISTINCT FROM at_observation->>'location_id' THEN 'LOCATION' WHEN actual_weight<>observed_book THEN 'WEIGHT' ELSE 'MATCH' END AS finding FROM raw)
 SELECT jsonb_build_object('stocktake_id',doc,'snapshot_revision',d.snapshot_revision::text,'snapshot_at',d.snapshot_at,'snapshot_version',d.snapshot_version,'close_revision',r::text,'pass',d.current_pass,'opening_weight',coalesce(sum(opening),0)::text,'movement_net',coalesce(sum(closing-opening),0)::text,'closing_weight',coalesce(sum(closing),0)::text,'rolled_count_weight',coalesce(sum(rolled_count),0)::text,'difference',coalesce(sum(rolled_count-closing),0)::text,'duplicates',count(*) FILTER(WHERE finding='DUPLICATE'),'unverified',count(*) FILTER(WHERE finding='UNVERIFIED_MOVEMENT'),'rows',coalesce(jsonb_agg(jsonb_build_object('bundle_no',no,'finding',finding,'opening',opening::text,'closing',closing::text,'movement_net',(closing-opening)::text,'actual_weight',actual_weight::text,'rolled_count',rolled_count::text,'difference',(rolled_count-closing)::text,'expected_location',CASE WHEN observed_book>0 THEN at_observation->>'location' ELSE NULL END,'actual_location',actual_location,'occurrences',occurrences,'weight_mismatch',actual_weight IS NOT NULL AND actual_weight<>observed_book,'location_mismatch',observed_book>0 AND actual_location_id::text IS DISTINCT FROM at_observation->>'location_id') ORDER BY no),'[]'::jsonb)) INTO result FROM rows;
 RETURN result;END $$;
CREATE FUNCTION stocktake_record(actor uuid,doc uuid,expected int,entries jsonb,source_kind text) RETURNS stocktakes LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d stocktakes;x jsonb;l locations;r bigint;BEGIN
 r:=v24_revision();SELECT * INTO d FROM stocktakes WHERE id=doc FOR UPDATE;PERFORM v24_count_require(actor,'stocktake:write',d.project_id,d.warehouse_id);
 IF d.status<>'OPEN' OR d.version<>expected OR jsonb_typeof(entries)<>'array' OR jsonb_array_length(entries) NOT BETWEEN 1 AND 500 OR source_kind NOT IN('MANUAL','EXCEL') THEN RAISE EXCEPTION 'Count state, version or batch invalid' USING ERRCODE='23514';END IF;
 FOR x IN SELECT * FROM jsonb_array_elements(entries) LOOP
 IF coalesce(x->>'bundle_no','')!~'^[A-Z0-9][A-Z0-9._/-]{0,79}$' OR coalesce(x->>'actual_weight','')!~'^\d{1,8}(\.\d{1,6})?$' OR length(coalesce(x->>'remark',''))>500 THEN RAISE EXCEPTION 'Invalid observed bundle or weight' USING ERRCODE='23514';END IF;
 SELECT * INTO l FROM locations WHERE id=(x->>'actual_location_id')::uuid AND warehouse_id=d.warehouse_id AND project_id=d.project_id;
 IF NOT FOUND OR(d.scope->>'yard_id' IS NOT NULL AND l.yard_id::text IS DISTINCT FROM d.scope->>'yard_id') OR(d.scope->>'location_id' IS NOT NULL AND l.id::text<>d.scope->>'location_id') THEN RAISE EXCEPTION 'Observation location outside task' USING ERRCODE='23514';END IF;
 INSERT INTO stocktake_observations(stocktake_id,pass,bundle_no,actual_location_id,actual_weight,observed_revision,counted_by,counted_at,remark,source,source_row) VALUES(doc,d.current_pass,x->>'bundle_no',l.id,(x->>'actual_weight')::numeric,r,actor,v24_posting_time(),coalesce(x->>'remark',''),source_kind,(x->>'source_row')::int);END LOOP;
 UPDATE stocktakes SET version=version+1 WHERE id=doc RETURNING * INTO d;INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data) VALUES(actor,'stocktake_observed','stocktakes',doc::text,jsonb_build_object('pass',d.current_pass,'rows',jsonb_array_length(entries),'source',source_kind));RETURN d;END $$;
CREATE FUNCTION stocktake_action(actor uuid,doc uuid,expected int,action text,payload jsonb) RETURNS stocktakes LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d stocktakes;report jsonb;note text;r bigint;BEGIN
 r:=v24_revision();SELECT * INTO d FROM stocktakes WHERE id=doc FOR UPDATE;IF NOT FOUND OR d.version<>expected THEN RAISE EXCEPTION 'Count version conflict' USING ERRCODE='23514';END IF;note:=trim(coalesce(payload->>'note',''));IF length(note) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'Count action explanation required' USING ERRCODE='23514';END IF;
 PERFORM v24_count_require(actor,CASE WHEN action IN('approve','reject','reconcile') THEN 'stocktake:review' ELSE 'stocktake:write' END,d.project_id,d.warehouse_id);
 IF action='submit' THEN IF d.status<>'OPEN' THEN RAISE EXCEPTION 'Count not open' USING ERRCODE='23514';END IF;UPDATE stocktakes SET status='SUBMITTED',close_revision=r WHERE id=doc;
 ELSIF action='recount' THEN IF d.status NOT IN('OPEN','REJECTED') OR d.current_pass>=10 THEN RAISE EXCEPTION 'Recount requires open or rejected count' USING ERRCODE='23514';END IF;UPDATE stocktakes SET status='OPEN',current_pass=current_pass+1,close_revision=NULL WHERE id=doc;
 ELSIF action='reconcile' THEN IF d.status<>'OPEN' THEN RAISE EXCEPTION 'Reconcile before submission' USING ERRCODE='23514';END IF;report:=stocktake_report(actor,doc);IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(report->'rows') x WHERE x->>'bundle_no'=payload->>'bundle_no' AND x->>'finding'='UNVERIFIED_MOVEMENT') THEN RAISE EXCEPTION 'No unverified movement for this bundle' USING ERRCODE='23514';END IF;INSERT INTO stocktake_reconciliations(stocktake_id,pass,bundle_no,covered_revision,reason,actor_id) VALUES(doc,d.current_pass,payload->>'bundle_no',r,note,actor);
 ELSIF action IN('approve','reject') THEN IF d.status<>'SUBMITTED' OR actor=d.created_by OR EXISTS(SELECT 1 FROM stocktake_observations WHERE stocktake_id=doc AND counted_by=actor) THEN RAISE EXCEPTION 'Independent count reviewer required' USING ERRCODE='23514';END IF;report:=stocktake_report(actor,doc);IF action='approve' AND((report->>'duplicates')::int>0 OR(report->>'unverified')::int>0) THEN RAISE EXCEPTION 'Resolve duplicates or unverified movements before approval' USING ERRCODE='23514';END IF;UPDATE stocktakes SET status=CASE WHEN action='approve' THEN 'APPROVED' ELSE 'REJECTED' END,reviewed_by=actor,reviewed_at=v24_posting_time(),review_note=note,approved_report=CASE WHEN action='approve' THEN report ELSE NULL END WHERE id=doc;
 ELSE RAISE EXCEPTION 'Unknown count action' USING ERRCODE='23514';END IF;
 UPDATE stocktakes SET version=version+1 WHERE id=doc RETURNING * INTO d;INSERT INTO stocktake_steps(stocktake_id,action,pass,actor_id,note) VALUES(doc,action,d.current_pass,actor,note);INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data) VALUES(actor,'stocktake_'||action,'stocktakes',doc::text,to_jsonb(d)-'approved_report');RETURN d;END $$;
REVOKE ALL ON FUNCTION stocktake_create(uuid,uuid,uuid,jsonb,uuid),stocktake_report(uuid,uuid),stocktake_record(uuid,uuid,int,jsonb,text),stocktake_action(uuid,uuid,int,text,jsonb),v24_count_require(uuid,text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION stocktake_create(uuid,uuid,uuid,jsonb,uuid),stocktake_report(uuid,uuid),stocktake_record(uuid,uuid,int,jsonb,text),stocktake_action(uuid,uuid,int,text,jsonb),v24_count_require(uuid,text,uuid,uuid) TO musonoi_app;
GRANT SELECT ON stocktakes,stocktake_snapshot,stocktake_observations,stocktake_reconciliations,stocktake_steps TO musonoi_app;
